tool_input.new_string:
beforeSubmit() {
  const error = this.validateFloodPayload(this.buildPayload()) || this.validatePostExtraForm()
  // 顺手刷新描红，点「编辑」回去就能看到哪几行还空着
  this.itemRequiredError = this.blankItemCount > 0
  this.deployRequiredError = this.isGroupNumRequired && !this.hasGroupNum
  if (error) { this.msgWarning(error); return false }
  return true
},
/**
 * 汛后检查提交前校验「整改与复盘」五项必填（禅道 7008，与 H5 口径一致）：
 * 整改措施 / 整改期限 / 整改状态 / 整改责任人 / 现场照片（PC 对应「检查文件上传」）。
 * 只挂 beforeSubmit：草稿保存（handleSave → saveFloodRecord allowBlankItems）不受影响。
 * 校验顺序与页面字段顺序一致，命中即返回可读文案，交由 msgWarning 提示并阻断提交。
 */
validatePostExtraForm() {
  if (!this.isPost) return ''
  const required = [
    ['rectifyMeasure', '请输入整改措施'],
    ['rectifyDeadline', '请选择整改期限'],
    ['rectifyState', '请选择整改状态'],
    ['rectifyUser', '请输入整改责任人'],
    ['inspectionFileUrl', '请上传现场照片']
  ]
  for (const [key, message] of required) {
    if (this.isBlankFill(this.form[key])) return message
  }
  return ''
},
handleSubmit() { if (!this.canSubmitFlood) return; this.msgWarning('请通过标准提交按钮发起流程') }

